import{_ as i,W as l,s as r,u as d,I as a,ah as o,w as e,Z as n,A as p}from"./chunks/framework.DRqsSc0o.js";import"./chunks/theme.DlTh90wK.js";const D=JSON.parse('{"title":"如何使用 DockerHub | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 DockerHub | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 DockerHub | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 DockerHub | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180129 How to Use DockerHub","title":"如何使用 DockerHub","tag":"201804"},"relativePath":"201804/20180129 How to Use DockerHub.md","filePath":"[post].md"}'),u={name:"201804/20180129 How to Use DockerHub.md"};function b(c,s,g,k,h,m){const t=l("Link");return d(),r("div",null,[s[30]||(s[30]=a("h1",{id:"如何使用-dockerhub",tabindex:"-1"},[e("如何使用 DockerHub "),a("a",{class:"header-anchor",href:"#如何使用-dockerhub","aria-label":"Permalink to 如何使用 DockerHub"},"​")],-1)),s[31]||(s[31]=a("blockquote",null,[a("p",null,"在这个 Docker 系列的最后一篇文章中，我们将讲述在 DockerHub 上使用和发布镜像。")],-1)),s[32]||(s[32]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/dockerhub-container.jpg?itok=tvraxGzh",alt:""})],-1)),a("p",null,[s[3]||(s[3]=e("在前面的文章中，我们了解到了基本的 ")),n(t,{href:"https://www.linux.com/blog/intro-to-linux/2017/12/container-basics-terms-you-need-know"},{default:p(()=>s[0]||(s[0]=[e("Docker 术语")])),_:1}),s[4]||(s[4]=e("，在 Linux 桌面、MacOS 和 Windows上 ")),n(t,{href:"https://www.linux.com/blog/learn/intro-to-linux/how-install-docker-ce-your-desktop"},{default:p(()=>s[1]||(s[1]=[e("如何安装 Docker")])),_:1}),s[5]||(s[5]=e("，")),n(t,{href:"https://linux.cn/article-9541-1.html"},{default:p(()=>s[2]||(s[2]=[e("如何创建容器镜像")])),_:1}),s[6]||(s[6]=e(" 并且在系统上运行它们。在本系列的最后一篇文章中，我们将讨论如何使用 DockerHub 中的镜像以及将自己的镜像发布到 DockerHub。"))]),s[33]||(s[33]=o(`<p>首先：什么是 DockerHub 以及为什么它很重要？DockerHub 是一个由 Docker 公司运行和管理的基于云的存储库。它是一个在线存储库，Docker 镜像可以由其他用户发布和使用。有两种库：公共存储库和私有存储库。如果你是一家公司，你可以在你自己的组织内拥有一个私有存储库，而公共镜像可以被任何人使用。</p><p>你也可以使用公开发布的官方 Docker 镜像。我使用了很多这样的镜像，包括我的试验 WordPress 环境、KDE plasma 应用程序等等。虽然我们上次学习了如何创建自己的 Docker 镜像，但你不必这样做。DockerHub 上发布了数千镜像供你使用。DockerHub 作为默认存储库硬编码到 Docker 中，所以当你对任何镜像运行 <code>docker pull</code> 命令时，它将从 DockerHub 下载。</p><h3 id="从-docker-hub-下载镜像并在本地运行" tabindex="-1">从 Docker Hub 下载镜像并在本地运行 <a class="header-anchor" href="#从-docker-hub-下载镜像并在本地运行" aria-label="Permalink to 从 Docker Hub 下载镜像并在本地运行">​</a></h3><p>开始请查看本系列的前几篇文章，以便继续。然后，一旦 Docker 在你的系统上运行，你就可以打开终端并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker images</span></span></code></pre></div><p>该命令将显示当前系统上所有的 docker 镜像。假设你想在本地机器上部署 Ubuntu，你可能会：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker pull ubuntu</span></span></code></pre></div><p>如果你的系统上已经存在 Ubuntu 镜像，那么该命令会自动将该系统更新到最新版本。因此，如果你想要更新现有的镜像，只需运行 <code>docker pull</code> 命令，易如反掌。这就像 <code>apt-get update</code> 一样，没有任何的混乱和麻烦。</p><p>你已经知道了如何运行镜像：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker run -it &lt;image name&gt;</span></span>
<span class="line"><span>$ docker run -it ubuntu</span></span></code></pre></div><p>命令提示符应该变为如下内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root@1b3ec4621737:/#</span></span></code></pre></div><p>现在你可以运行任何属于 Ubuntu 的命令和实用程序，这些都被包含在内而且安全。你可以在 Ubuntu 上运行你想要的所有实验和测试。一旦你完成了测试，你就可以销毁镜像并下载一个新的。在虚拟机中不存在系统开销。</p><p>你可以通过运行 exit 命令退出该容器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ exit</span></span></code></pre></div><p>现在假设你想在系统上安装 Nginx，运行 <code>search</code> 命令来找到需要的镜像：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker search nginx</span></span></code></pre></div><p><img src="https://lh3.googleusercontent.com/aizMFFysICAEsgDDYrsrlqwoCgGbWVHtcOzgV9mAtV8IdBZgHPJTdHIZhWBNCRvOyJb108ZBajJ_Nz10yCxGSvk-AF-yvFxpojLdVu3Jjihcwaup6CQLc67A5nglBuGDaOZWcrbV" alt=""></p><p>正如你所看到的，DockerHub 上有很多 Nginx 镜像。为什么？因为任何人都可以发布镜像，各种镜像针对不同的项目进行了优化，因此你可以选择合适的镜像。你只需要为你的需求安装合适的镜像。</p><p>假设你想要拉取 Bitnami 的 Nginx 镜像：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker pull bitnami/nginx</span></span></code></pre></div><p>现在运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker run -it bitnami/nginx</span></span></code></pre></div><h3 id="如何发布镜像到-docker-hub" tabindex="-1">如何发布镜像到 Docker Hub？ <a class="header-anchor" href="#如何发布镜像到-docker-hub" aria-label="Permalink to 如何发布镜像到 Docker Hub？">​</a></h3>`,24)),a("p",null,[s[9]||(s[9]=e("在此之前，")),n(t,{href:"https://linux.cn/article-9541-1.html"},{default:p(()=>s[7]||(s[7]=[e("我们学习了如何创建 Docker 镜像")])),_:1}),s[10]||(s[10]=e("，我们可以轻松地将该镜像发布到 DockerHub 中。首先，你需要登录 DockerHub，如果没有账户，请 ")),n(t,{href:"https://hub.docker.com/"},{default:p(()=>s[8]||(s[8]=[e("创建账户")])),_:1}),s[11]||(s[11]=e("。然后，你可以打开终端应用，登录："))]),s[34]||(s[34]=o('<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker login --username=&lt;USERNAME&gt;</span></span></code></pre></div><p>将 “&lt;USERNAME&gt;” 替换为你自己的 Docker Hub 用户名。我这里是 arnieswap：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker login --username=arnieswap</span></span></code></pre></div><p>输入密码，你就登录了。现在运行 <code>docker images</code> 命令来获取你上次创建的镜像的 ID。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker images</span></span></code></pre></div><p><img src="https://lh6.googleusercontent.com/tW1jDOugkX7J2FfyFyToM6B8m5OYFwMba-Ag5aezVGf2A5gsKJ47QrCh_TOKWgIKfE824Uc2Cwwwj9jWps1yJlUZqDyIceVQs-nEbKavFDxuUxLyd4thBA4_rsXrQH4r7hrG8FnD" alt=""></p>',6)),a("p",null,[s[13]||(s[13]=e("现在，假设你希望将镜像 ")),s[14]||(s[14]=a("code",null,"ng",-1)),s[15]||(s[15]=e(" 推送到 DockerHub，首先，我们需要标记该镜像（")),n(t,{href:"https://www.linux.com/blog/intro-to-linux/2017/12/container-basics-terms-you-need-know"},{default:p(()=>s[12]||(s[12]=[e("了解更多关于标记的信息")])),_:1}),s[16]||(s[16]=e("）："))]),s[35]||(s[35]=o(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker tag e7083fd898c7 arnieswap/my_repo:testing</span></span></code></pre></div><p>现在推送镜像：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker push arnieswap/my_repo</span></span></code></pre></div><p>推送指向的是 [docker.io/arnieswap/my_repo] 仓库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12628b20827e: Pushed</span></span>
<span class="line"><span>8600ee70176b: Mounted from library/ubuntu</span></span>
<span class="line"><span>2bbb3cec611d: Mounted from library/ubuntu</span></span>
<span class="line"><span>d2bb1fc88136: Mounted from library/ubuntu</span></span>
<span class="line"><span>a6a01ad8b53f: Mounted from library/ubuntu</span></span>
<span class="line"><span>833649a3e04c: Mounted from library/ubuntu</span></span>
<span class="line"><span>testing: digest: sha256:286cb866f34a2aa85c9fd810ac2cedd87699c02731db1b8ca1cfad16ef17c146 size: 1569</span></span></code></pre></div><p>哦耶！你的镜像正在上传。一旦完成，打开 DockerHub，登录到你的账户，你就能看到你的第一个 Docker 镜像。现在任何人都可以部署你的镜像。这是开发软件和发布软件最简单，最快速的方式。无论你何时更新镜像，用户都可以简单地运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker run arnieswap/my_repo</span></span></code></pre></div><p>现在你知道为什么人们喜欢 Docker 容器了。它解决了传统工作负载所面临的许多问题，并允许你在任何时候开发、测试和部署应用程序。通过遵循本系列中的步骤，你自己可以尝试以下。</p><hr>`,9)),a("p",null,[s[18]||(s[18]=e("via: ")),n(t,{href:"https://www.linux.com/blog/learn/intro-to-linux/2018/1/how-use-dockerhub"},{default:p(()=>s[17]||(s[17]=[e("https://www.linux.com/blog/learn/intro-to-linux/2018/1/how-use-dockerhub")])),_:1})]),a("p",null,[s[22]||(s[22]=e("作者：")),n(t,{href:"https://www.linux.com/users/arnieswap"},{default:p(()=>s[19]||(s[19]=[e("Swapnil Bhartiya")])),_:1}),s[23]||(s[23]=e(" 译者：")),n(t,{href:"https://github.com/MjSeven"},{default:p(()=>s[20]||(s[20]=[e("MjSeven")])),_:1}),s[24]||(s[24]=e(" 校对：")),n(t,{href:"https://github.com/wxy"},{default:p(()=>s[21]||(s[21]=[e("wxy")])),_:1})]),a("p",null,[s[27]||(s[27]=e("本文由 ")),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>s[25]||(s[25]=[e("LCTT")])),_:1}),s[28]||(s[28]=e(" 原创编译，")),n(t,{href:"https://linux.cn/"},{default:p(()=>s[26]||(s[26]=[e("Linux中国")])),_:1}),s[29]||(s[29]=e(" 荣誉推出"))])])}const C=i(u,[["render",b]]);export{D as __pageData,C as default};
